BEGIN TRANSACTION;
CREATE TABLE call_units (
    call INTEGER NOT NULL REFERENCES calls(id) ON DELETE CASCADE,
    site TEXT NOT NULL,
    unit INTEGER NOT NULL,
    started_ms INTEGER NOT NULL,
    primary_src INTEGER NOT NULL
);
CREATE TABLE calls (
    id INTEGER PRIMARY KEY,
    site TEXT NOT NULL,
    call_id INTEGER NOT NULL,
    started_ms INTEGER NOT NULL,
    ended_ms INTEGER NOT NULL,
    tg INTEGER NOT NULL,
    source INTEGER,
    freq_hz INTEGER,
    chain INTEGER NOT NULL DEFAULT 0,
    encrypted INTEGER NOT NULL,
    followed INTEGER NOT NULL,
    not_followed TEXT,
    voice_ms INTEGER NOT NULL,
    grant_ms INTEGER NOT NULL,
    imbe INTEGER NOT NULL DEFAULT 0,
    vocoder_errors INTEGER NOT NULL DEFAULT 0,
    close_reason TEXT, channel TEXT,
    UNIQUE(site, call_id, started_ms)
);
CREATE TABLE hour_tg (
    site TEXT NOT NULL,
    t INTEGER NOT NULL,
    tg INTEGER NOT NULL,
    calls INTEGER NOT NULL,
    followed INTEGER NOT NULL,
    encrypted INTEGER NOT NULL,
    voice_ms INTEGER NOT NULL,
    clear_grant_ms INTEGER NOT NULL,
    enc_grant_ms INTEGER NOT NULL,
    voiced_grant_ms INTEGER NOT NULL,
    first_ms INTEGER NOT NULL,
    last_ms INTEGER NOT NULL,
    PRIMARY KEY(site, t, tg)
) WITHOUT ROWID;
CREATE TABLE hour_unit (
    site TEXT NOT NULL,
    t INTEGER NOT NULL,
    unit INTEGER NOT NULL,
    tg INTEGER NOT NULL,
    calls INTEGER NOT NULL,
    encrypted INTEGER NOT NULL,
    voice_ms INTEGER NOT NULL,
    clear_grant_ms INTEGER NOT NULL,
    enc_grant_ms INTEGER NOT NULL,
    last_ms INTEGER NOT NULL,
    PRIMARY KEY(site, t, unit, tg)
) WITHOUT ROWID;
CREATE TABLE site_stats (
    site TEXT PRIMARY KEY,
    calls INTEGER NOT NULL,
    first_ms INTEGER NOT NULL,
    last_ms INTEGER NOT NULL
);
CREATE TABLE unit_events (
    site TEXT NOT NULL,
    unit INTEGER NOT NULL,
    tg INTEGER NOT NULL,
    kind TEXT NOT NULL,
    first_ms INTEGER NOT NULL,
    last_ms INTEGER NOT NULL,
    count INTEGER NOT NULL,
    PRIMARY KEY(site, unit, tg, kind)
);
CREATE INDEX calls_site_time ON calls(site, started_ms);
CREATE INDEX calls_site_tg ON calls(site, tg, started_ms);
CREATE INDEX call_units_site_unit ON call_units(site, unit, started_ms);
CREATE INDEX call_units_call ON call_units(call);
CREATE INDEX hour_unit_unit ON hour_unit(site, unit, t);
COMMIT;
